package com.ilia.gikashvili.archmain.admin.service;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.scheduling.annotation.Async; import com.ilia.gikashvili.archmain.admin.repository.BackgroundJobRepository; import com.ilia.gikashvili.archmain.admin.entity.BackgroundJob; import com.ilia.gikashvili.archmain.notification.service.NotificationService; import com.ilia.gikashvili.archmain.common.exception.*;
@Service public class BackgroundJobService {private final BackgroundJobRepository repo;private final NotificationService notifications;public BackgroundJobService(BackgroundJobRepository r,NotificationService n){repo=r;notifications=n;}
public UUID welcome(UUID uid){var j=new BackgroundJob();j.setUserId(uid);j.setType("WELCOME_NOTIFICATION");j.setStatus("PENDING");return repo.save(j).getId();}
@Async public void execute(UUID id){var j=repo.findById(id).orElseThrow(()->new NotFoundException("Job",id));j.setStatus("RUNNING");j.setAttempts(j.getAttempts()+1);repo.save(j);try{if(!"WELCOME_NOTIFICATION".equals(j.getType()))throw new IllegalStateException("Unsupported job type");notifications.notify(j.getUserId(),"WELCOME","Welcome to ArchMain","Your account is ready.","/projects");j.setStatus("COMPLETED");j.setError(null);}catch(Exception e){j.setStatus("FAILED");j.setError(e.getClass().getSimpleName());}repo.save(j);}
public BackgroundJob retry(UUID id){var j=repo.findById(id).orElseThrow(()->new NotFoundException("Job",id));if(!"FAILED".equals(j.getStatus()))throw new ConflictException("Only failed jobs may be retried");j.setStatus("PENDING");j.setError(null);return repo.save(j);}
}
